int main(int argc,char** argv){try{small();if(argc==2)stock(argv[1]);else check(argc==1);std::cout<<"Line file runtime checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
